    c := array[0..N] of 0
    a[1] := 1
    for m from 1 to N-1:
        for k from 1 to m:
            c[k] := 0
            for each divisor d of k:
                c[k] := c[k] + d * a[d]
        S := 0
        for k from 1 to m:
            S := S + c[k] * a[m+1-k]
        assert S mod m == 0          # integrality: division is exact
        a[m+1] := S div m
    return a

